let cleanse_aggregate_definition_claims=[
 ("bp_e2_cleanse_call_post","full",parse_term "forall m pc stackpointer ra p n s t.\n    bp_e2_cleanse_call_post pc stackpointer ra p n m s t <=>\n    read RIP t = ra /\\\n    val (read RSP t) = val stackpointer + 8 /\\\n    (forall i. i < n ==> read memory t (word_add p (word i)) = word 0) /\\\n    (forall a. ~assurance_region p n (val a) ==> read memory t a = m a) /\\\n    bytes_loaded t (word pc) openssl_cleanse_mc /\\\n    read (memory :> bytes64 stackpointer) t = ra /\\\n    (MAYCHANGE [RIP; RSP; RAX; RDI; RSI] ,,\n     MAYCHANGE SOME_FLAGS ,,\n     MAYCHANGE [memory :> bytes (p,n)] ,,\n     MAYCHANGE [events])\n    s\n    t",bp_e2_cleanse_call_post);
 ("bp_e2_cleanse_public_pre","full",parse_term "forall file_bytes initial_rw padding stackpointer ra p n m s rp ordinary xp wp a.\n    bp_e2_cleanse_public_pre file_bytes initial_rw padding stackpointer ra p\n    n\n    m\n    rp\n    wp\n    xp\n    ordinary\n    (s,a) <=>\n    clw_file_code file_bytes /\\\n    fb_full_image file_bytes initial_rw padding m /\\\n    bp_e2_cleanse_pre 270800848 stackpointer ra p n m rp wp xp ordinary s /\\\n    (forall addr.\n         lw_image_domain addr\n         ==> rp addr /\\\n             ordinary addr /\\\n             (xp addr <=> lw_execute addr) /\\\n             (wp addr <=> lw_image_write addr)) /\\\n    assurance_canonical48 (val (read ABI_FS_BASE a))",bp_e2_cleanse_public_pre);
 ("bp_e2_cleanse_public_post","full",parse_term "forall stackpointer ra p n m s a t.\n    bp_e2_cleanse_public_post stackpointer ra p n m s a t <=>\n    bp_e2_cleanse_call_post 270800848 stackpointer ra p n m s (FST t) /\\\n    SND t = a /\\\n    abi_required_controls_preserved a (SND t)",bp_e2_cleanse_public_post);
 ("bp_e2_cleanse_pre","full",parse_term "forall m ra s xp rp wp ordinary pc p n stackpointer.\n    bp_e2_cleanse_pre pc stackpointer ra p n m rp wp xp ordinary s <=>\n    n < 2 EXP 64 /\\\n    pc + 97 <= 2 EXP 64 /\\\n    bytes_loaded s (word pc) openssl_cleanse_mc /\\\n    read RIP s = word pc /\\\n    read RSP s = stackpointer /\\\n    read (memory :> bytes64 stackpointer) s = ra /\\\n    C_ARGUMENTS [p; word n] s /\\\n    read memory s = m /\\\n    val stackpointer MOD 16 = 8 /\\\n    val stackpointer + 8 < 2 EXP 64 /\\\n    assurance_canonical48 (val ra) /\\\n    ~(ra = word pc) /\\\n    (read DF s <=> false) /\\\n    ~bit 18 (read rflags s) /\\\n    assurance_span_ok (\\a. xp a /\\ ordinary a) pc 97 /\\\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val stackpointer) 8 /\\\n    assurance_span_ok (\\a. wp a /\\ ordinary a) (val p) n /\\\n    (forall a. ~(assurance_region p n a /\\ assurance_region (word pc) 97 a)) /\\\n    (forall a.\n         ~(assurance_region p n a /\\ assurance_region stackpointer 8 a))",bp_e2_cleanse_pre);
 ("bp_e2_cleanse_allowed_read","full",parse_term "forall rp ordinary stackpointer a.\n    bp_e2_cleanse_allowed_read rp ordinary stackpointer a <=>\n    rp a /\\ ordinary a /\\ assurance_region stackpointer 8 a",bp_e2_cleanse_allowed_read);
 ("bp_e2_cleanse_allowed_write","full",parse_term "forall wp ordinary p n a.\n    bp_e2_cleanse_allowed_write wp ordinary p n a <=>\n    wp a /\\ ordinary a /\\ assurance_region p n a",bp_e2_cleanse_allowed_write);
 ("bp_e2_cleanse_allowed_fetch","full",parse_term "forall xp ordinary pc a.\n    bp_e2_cleanse_allowed_fetch xp ordinary pc a <=>\n    xp a /\\ ordinary a /\\ assurance_region (word pc) 97 a",bp_e2_cleanse_allowed_fetch);
 ("cleanse_functional_steps","full",parse_term "forall n p.\n    cleanse_functional_steps p n =\n    (if n < 15\n     then 4 * n + 7\n     else let a = (8 - val p MOD 8) MOD 8 in\n          9 + 6 * a + 5 * (n - a) DIV 8 + 4 * (n - a) MOD 8)",cleanse_functional_steps);
 ("cleanse_access_count","full",parse_term "forall n p.\n    cleanse_access_count p n =\n    (if n < 15\n     then 4 * n + 7\n     else let a = (8 - val p MOD 8) MOD 8 in\n          let k = (n - a) DIV 8 in\n          let r = (n - a) MOD 8 in 9 + 6 * a + 5 * k + 4 * r)",cleanse_access_count);
 ("cleanse_access_covered_step","full",parse_term "forall rp wp xp remaining s' pc s.\n    cleanse_access_covered_step pc rp wp xp remaining s s' <=>\n    assurance_zero_step rp wp xp remaining s s' /\\\n    (exists off len inst.\n         read RIP s = word (pc + off) /\\\n         abi_cleanse_site off len inst /\\\n         x86_decode s (read RIP s) (len,inst))",cleanse_access_covered_step);
 ("cleanse_access_return_post","full",parse_term "forall ra stackpointer s pc.\n    cleanse_access_return_post pc stackpointer ra s <=>\n    read RIP s = ra /\\\n    read RSP s = word_add stackpointer (word 8) /\\\n    bytes_loaded s (word pc) openssl_cleanse_mc",cleanse_access_return_post);
 ("assurance_checked_run","full",parse_term "(assurance_checked_run 0 P C s <=> P s) /\\\n(assurance_checked_run (SUC n) P C s <=>\n (exists s'. x86 s s') /\\\n (forall s'. x86 s s' ==> C (SUC n) s s' /\\ assurance_checked_run n P C s'))",assurance_checked_run);
 ("assurance_step_policy","full",parse_term "forall xp s' s rp wp.\n    assurance_step_policy rp wp xp s s' <=>\n    (exists len inst d.\n         x86_decode s (read RIP s) (len,inst) /\\\n         assurance_span_ok xp (val (read RIP s)) len /\\\n         read events s' = APPEND d (read events s) /\\\n         ALL (assurance_event_policy rp wp) d)",assurance_step_policy);
 ("assurance_zero_step","full",parse_term "forall rp wp xp remaining s s'.\n    assurance_zero_step rp wp xp remaining s s' <=>\n    assurance_step_policy rp wp xp s s' /\\\n    (remaining = 1 ==> assurance_actual_ret 2 s s')",assurance_zero_step);
 ("assurance_event_policy","full",parse_term "forall e rp wp.\n    assurance_event_policy rp wp e <=>\n    (match e with\n       EventLoad (adr,width) -> assurance_span_ok rp (val adr) width\n     | EventStore (adr,width) -> assurance_span_ok wp (val adr) width\n     | _ -> true)",assurance_event_policy);
 ("assurance_fetch_policy","full",parse_term "forall xp obs.\n    assurance_fetch_policy xp obs <=>\n    assurance_span_ok xp (val (FST obs)) (FST (SND obs))",assurance_fetch_policy);
 ("assurance_region","full",parse_term "forall a p n. assurance_region p n a <=> val p <= a /\\ a < val p + n",assurance_region);
 ("assurance_span_ok","full",parse_term "forall width perm a.\n    assurance_span_ok perm a width <=>\n    a + width <= 2 EXP 64 /\\\n    (forall j. j < width ==> assurance_canonical48 (a + j) /\\ perm (a + j))",assurance_span_ok);
 ("assurance_canonical48","full",parse_term "forall a.\n    assurance_canonical48 a <=>\n    a < 2 EXP 64 /\\ (a < 2 EXP 47 \\/ 2 EXP 64 - 2 EXP 47 <= a)",assurance_canonical48);
 ("abi_cleanse_scalar_instruction","full",parse_term "forall inst.\n    abi_cleanse_scalar_instruction inst <=>\n    abi_scalar_instruction inst \\/\n    (exists r imm. inst = SUB (% (Gpr r Full_64)) (Imm8 imm)) \\/\n    (exists r imm. inst = TEST (% (Gpr r Full_64)) (Imm32 imm))",abi_cleanse_scalar_instruction);
 ("abi_cleanse_scalar_extended_step","full",parse_term "forall s s' a' a.\n    abi_cleanse_scalar_extended_step (s,a) (s',a') <=>\n    (exists len inst.\n         x86_decode s (read RIP s) (len,inst) /\\\n         (RIP := word_add (read RIP s) (word len) ,, x86_execute inst) s s' /\\\n         (abi_cleanse_scalar_instruction inst ==> a' = a))",abi_cleanse_scalar_extended_step);
 ("abi_all_decodes_cleanse_scalar","full",parse_term "forall s.\n    abi_all_decodes_cleanse_scalar s <=>\n    (forall len inst.\n         x86_decode s (read RIP s) (len,inst)\n         ==> abi_cleanse_scalar_instruction inst)",abi_all_decodes_cleanse_scalar);
 ("abi_required_controls_preserved","full",parse_term "forall a' a.\n    abi_required_controls_preserved a a' <=>\n    read ABI_X87_CW a' = read ABI_X87_CW a /\\\n    word_and (read ABI_MXCSR a') (word 65472) =\n    word_and (read ABI_MXCSR a) (word 65472) /\\\n    read ABI_FS_SELECTOR a' = read ABI_FS_SELECTOR a /\\\n    read ABI_FS_BASE a' = read ABI_FS_BASE a",abi_required_controls_preserved);
 ("clw_file_code","full",parse_term "forall file_bytes.\n    clw_file_code file_bytes <=>\n    (forall i. i < 97 ==> file_bytes (2365392 + i) = EL i openssl_cleanse_mc)",clw_file_code);
 ("clw_full_pre","full",parse_term "forall file_bytes initial_rw padding image high_first p n.\n    clw_full_pre file_bytes initial_rw padding image p n high_first <=>\n    fb_full_image file_bytes initial_rw padding\n    (read memory (FST (clw_machine image p n high_first))) /\\\n    bp_e2_cleanse_pre 270800848 (word 3145736) (word 4194304) p n\n    (clw_memory image p n high_first)\n    (clw_read p n)\n    (clw_write p n)\n    lw_execute\n    (clw_ordinary p n)\n    (FST (clw_machine image p n high_first)) /\\\n    fb_abi_initial_fields (SND (clw_machine image p n high_first)) /\\\n    (forall a. fb_tls_page a ==> clw_read p n a /\\ clw_ordinary p n a) /\\\n    assurance_canonical48\n    (val (read ABI_FS_BASE (SND (clw_machine image p n high_first)))) /\\\n    (forall a.\n         lw_image_domain a\n         ==> clw_read p n a /\\\n             clw_ordinary p n a /\\\n             (lw_execute a <=> lw_image_execute a) /\\\n             (clw_write p n a <=> lw_image_write a))",clw_full_pre);
 ("clw_machine","full",parse_term "forall image p n high_first.\n    clw_machine image p n high_first =\n    clw_state image p n high_first,fb_initial_abi",clw_machine);
 ("clw_memory","full",parse_term "forall image p n high_first.\n    clw_memory image p n high_first = lw_memory image p p n high_first",clw_memory);
 ("clw_state","full",parse_term "forall image p n high_first.\n    clw_state image p n high_first =\n    x86state_RECORD (word 270800848)\n    (\\r.\n         if r = word 7\n         then p\n         else if r = word 6\n              then word n\n              else if r = word 4 then word 3145736 else word 0)\n    (\\z. word 0)\n    (\\k. word 0)\n    (word 2)\n    (clw_memory image p n high_first)\n    []",clw_state);
 ("clw_read","full",parse_term "forall p n a. clw_read p n a <=> fb_read p p n a",clw_read);
 ("clw_write","full",parse_term "forall p n a. clw_write p n a <=> lw_image_write a \\/ lw_pagecover p n a",clw_write);
 ("clw_ordinary","full",parse_term "forall p n a. clw_ordinary p n a <=> fb_ordinary p p n a",clw_ordinary);
 ("fb_full_image","full",parse_term "forall image file_bytes initial_rw padding.\n    fb_full_image file_bytes initial_rw padding image <=>\n    (forall a.\n         lw_image_domain (val a)\n         ==> image a = fb_reference_image file_bytes initial_rw padding a)",fb_full_image);
 ("fb_reference_image","full",parse_term "forall file_bytes initial_rw padding a.\n    fb_reference_image file_bytes initial_rw padding a =\n    (if fb_immutable (val a)\n     then file_bytes (val a - 268435456)\n     else if fb_initialized_rw (val a) then initial_rw a else padding a)",fb_reference_image);
 ("fb_immutable","full",parse_term "forall a.\n    fb_immutable a <=>\n    268435456 <= a /\\ a < 269241296 \\/\n    269242368 <= a /\\ a < 271856841 \\/\n    271859712 <= a /\\ a < 272767552",fb_immutable);
 ("fb_initialized_rw","full",parse_term "forall a. fb_initialized_rw a <=> 272772688 <= a /\\ a < 273192368",fb_initialized_rw);
