 ("bp_e2_cleanse_pre","body",parse_term "bp_e2_cleanse_pre pc stackpointer ra p n m rp wp xp ordinary (s:x86state) <=>\n    n<2 EXP 64 /\\ pc+97<=2 EXP 64 /\\\n    bytes_loaded s (word pc) openssl_cleanse_mc /\\\n    read RIP s=word pc /\\ read RSP s=stackpointer /\\\n    read (memory :> bytes64 stackpointer) s=ra /\\\n    C_ARGUMENTS [p;word n] s /\\ read memory s=m /\\\n    val(stackpointer:int64) MOD 16=8 /\\ val stackpointer+8<2 EXP 64 /\\\n    assurance_canonical48(val(ra:int64)) /\\ ~(ra=word pc) /\\\n    read DF s=F /\\ ~bit 18(read rflags s) /\\\n    assurance_span_ok (\\a. xp a /\\ ordinary a) pc 97 /\\\n    assurance_span_ok (\\a. rp a /\\ ordinary a) (val stackpointer) 8 /\\\n    assurance_span_ok (\\a. wp a /\\ ordinary a) (val(p:int64)) n /\\\n    (!a. ~(assurance_region p n a /\\ assurance_region (word pc) 97 a)) /\\\n    (!a. ~(assurance_region p n a /\\ assurance_region stackpointer 8 a))",bp_e2_cleanse_pre);
